from pathlib import Path
import re, hashlib

CORE = Path('lab-selector-v4/selector-nubes-multistream-core.html')
WRAP = Path('lab-selector-v4/index.html')
core = CORE.read_text(encoding='utf-8')
wrap = WRAP.read_text(encoding='utf-8')

def git_blob_sha(text):
    b=text.encode('utf-8')
    return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()

assert git_blob_sha(core) == '32fb3a5476129fe128e3f2faccfa651979c50dff', git_blob_sha(core)
assert git_blob_sha(wrap) == '765e49c4af0afa89b940a58741a05edd4ae47d1f', git_blob_sha(wrap)

insert = r'''
// LAB flat-memory exact index. Normal V2.1 flow is untouched; this only replaces
// the impossible all-stroke JS materialization for exceptionally large, single-stream,
// Form-free pages. It keeps exact byte ranges and only retains curved strokes, which
// are the selectable revision-cloud arcs. No alternate mapping/causal route is added.
let flatVerifyCache=null;
const flatWs=c=>c===9||c===10||c===11||c===12||c===13||c===32;
const flatDelim=c=>flatWs(c)||c===91||c===93||c===40||c===41||c===60||c===62||c===47||c===37;
function flatAscii(u,a,b){let s='';for(let i=a;i<b;i++)s+=String.fromCharCode(u[i]);return s}
function flatHasFormXObject(page){try{const res=deepPageResources(page.getObject()),xd=deepObj(deepObj(res)?.get?.('XObject'));if(!xd?.isDictionary?.())return false;const ks=xd.getKeys?.()||[];for(const k of ks){const r=xd.get(k);if(r?.isStream?.()&&deepName(deepObj(r)?.get?.('Subtype'))==='Form')return true}let found=false;if(!ks.length&&xd.forEach)xd.forEach(v=>{if(v?.isStream?.()&&deepName(deepObj(v)?.get?.('Subtype'))==='Form')found=true});return found}catch(_){return true}}
function flatHugeInfo(page,force=false){const roots=refs(page);if(roots.length!==1||flatHasFormXObject(page))return null;let compressed=0;try{compressed=deepNum(deepObj(roots[0])?.get?.('Length'))}catch(_){}if(!force&&(!Number.isFinite(compressed)||compressed<10_000_000))return null;return{ref:roots[0],compressed}}
function flatCurveCmds(u,a0,b0,base){let i=a0,A=base[0],B=base[1],C=base[2],D=base[3],E=base[4],F=base[5],stack=[],nv=new Float64Array(8),nn=0,cmds=[],cur=null,start=null,closed=false;const put=v=>{if(nn<8)nv[nn++]=v;else{for(let k=1;k<8;k++)nv[k-1]=nv[k];nv[7]=v}},tail=k=>nv[nn-k],P=(x,y)=>[A*x+C*y+E,B*x+D*y+F];while(i<b0){let c=u[i];if(flatWs(c)){i++;continue}if(c===37){while(i<b0&&u[i]!==10&&u[i]!==13)i++;continue}const st=i;if(c===40){i++;let d=1;while(i<b0&&d){c=u[i];if(c===92){i+=2;continue}if(c===40)d++;else if(c===41)d--;i++}nn=0;continue}if(c===60){if(i+1<b0&&u[i+1]===60){i+=2}else{i++;while(i<b0&&u[i]!==62)i++;if(i<b0)i++;nn=0;continue}}else if(c===91){i++;let d=1;while(i<b0&&d){c=u[i];if(c===40){i++;let q=1;while(i<b0&&q){c=u[i];if(c===92){i+=2;continue}if(c===40)q++;else if(c===41)q--;i++}continue}if(c===91)d++;else if(c===93)d--;i++}nn=0;continue}else if(c===47){i++;while(i<b0&&!flatDelim(u[i]))i++;continue}else while(i<b0&&!flatDelim(u[i]))i++;const tok=flatAscii(u,st,i),fc=tok.charCodeAt(0);if(tok&&((fc>=48&&fc<=57)||fc===43||fc===45||fc===46)){const z=Number(tok);if(Number.isFinite(z)){put(z);continue}}const op=tok;if(op==='q'){stack.push(A,B,C,D,E,F)}else if(op==='Q'){if(stack.length>=6){F=stack.pop();E=stack.pop();D=stack.pop();C=stack.pop();B=stack.pop();A=stack.pop()}}else if(op==='cm'&&nn>=6){const a=tail(6),b=tail(5),c2=tail(4),d=tail(3),e=tail(2),f=tail(1),na=A*a+C*b,nb=B*a+D*b,nc=A*c2+C*d,nd=B*c2+D*d,ne=A*e+C*f+E,nf=B*e+D*f+F;A=na;B=nb;C=nc;D=nd;E=ne;F=nf}else if(op==='m'&&nn>=2){const p=P(tail(2),tail(1));cmds.push(['M',p[0],p[1]]);cur=p;start=p}else if(op==='l'&&nn>=2&&cur){const p=P(tail(2),tail(1));cmds.push(['L',p[0],p[1]]);cur=p}else if(op==='c'&&nn>=6&&cur){const p1=P(tail(6),tail(5)),p2=P(tail(4),tail(3)),p3=P(tail(2),tail(1));cmds.push(['C',p1[0],p1[1],p2[0],p2[1],p3[0],p3[1]]);cur=p3}else if(op==='v'&&nn>=4&&cur){const p1=cur,p2=P(tail(4),tail(3)),p3=P(tail(2),tail(1));cmds.push(['C',p1[0],p1[1],p2[0],p2[1],p3[0],p3[1]]);cur=p3}else if(op==='y'&&nn>=4&&cur){const p1=P(tail(4),tail(3)),p3=P(tail(2),tail(1));cmds.push(['C',p1[0],p1[1],p3[0],p3[1],p3[0],p3[1]]);cur=p3}else if(op==='re'&&nn>=4){const x=tail(4),y=tail(3),w=tail(2),h=tail(1),p0=P(x,y),p1=P(x+w,y),p2=P(x+w,y+h),p3=P(x,y+h);cmds.push(['M',p0[0],p0[1]],['L',p1[0],p1[1]],['L',p2[0],p2[1]],['L',p3[0],p3[1]],['Z']);cur=p0;start=p0;closed=true}else if(op==='h'&&cur){cmds.push(['Z']);cur=start;closed=true}else if(op==='s'||op==='b'||op==='b*'){if(cur&&!closed)cmds.push(['Z']);closed=true}nn=0}return{cmds,closed}}
function flatMetrics(cmds,bbox,first,last){const d=Math.max(.001,diag(bbox)),chord=first&&last?Math.hypot(last[0]-first[0],last[1]-first[1]):0;let plen=0,cur=null,start=null,closed=false;for(const c of cmds){if(c[0]==='M'){cur=[c[1],c[2]];start=cur}else if(c[0]==='L'&&cur){const q=[c[1],c[2]];plen+=Math.hypot(q[0]-cur[0],q[1]-cur[1]);cur=q}else if(c[0]==='C'&&cur){const p0=cur,p1=[c[1],c[2]],p2=[c[3],c[4]],p3=[c[5],c[6]];let q=p0;for(let k=1;k<=8;k++){const t=k/8,v=1-t,n=[v*v*v*p0[0]+3*v*v*t*p1[0]+3*v*t*t*p2[0]+t*t*t*p3[0],v*v*v*p0[1]+3*v*v*t*p1[1]+3*v*t*t*p2[1]+t*t*t*p3[1]];plen+=Math.hypot(n[0]-q[0],n[1]-q[1]);q=n}cur=p3}else if(c[0]==='Z'&&cur&&start){plen+=Math.hypot(start[0]-cur[0],start[1]-cur[1]);cur=start;closed=true}}return{closed:closed||chord/d<=.045,chordNorm:chord/d,lengthNorm:plen/d}}
function flatGiantExactModel(page,force=false){const info=flatHugeInfo(page,force);if(!info)return null;const ref=info.ref,buf=ref.readStream(),u=U(buf),sourceBase=deepKey(ref),locators=new Map([[sourceBase,{root:0,names:[]}]]);let pageBase=[1,0,0,1,0,0];try{pageBase=mupdf.Matrix.invert(page.getTransform())}catch(_){}let A=pageBase[0],B=pageBase[1],C=pageBase[2],D=pageBase[3],E=pageBase[4],F=pageBase[5],R=0,G=0,BL=0,W=1,stack=[],i=0,n=u.length,nv=new Float64Array(8),ns=new Uint32Array(8),nn=0,pOn=false,pStart=0,pA=1,pB=0,pC=0,pD=1,pE=0,pF=0,x0=0,y0=0,x1=0,y1=0,fx=0,fy=0,lx=0,ly=0,lines=0,curves=0,pR=0,pG=0,pBL=0,pW=1,out=[];const put=(v,s)=>{if(nn<8){nv[nn]=v;ns[nn]=s;nn++}else{for(let k=1;k<8;k++){nv[k-1]=nv[k];ns[k-1]=ns[k]}nv[7]=v;ns[7]=s}},tail=k=>nv[nn-k],tailS=k=>ns[nn-k],add=(x,y)=>{if(!pOn){x0=x1=fx=lx=x;y0=y1=fy=ly=y;pOn=true}else{if(x<x0)x0=x;if(y<y0)y0=y;if(x>x1)x1=x;if(y>y1)y1=y;lx=x;ly=y}},P=(x,y)=>[A*x+C*y+E,B*x+D*y+F],begin=s=>{if(!pOn){pStart=s;pA=A;pB=B;pC=C;pD=D;pE=E;pF=F;pR=R;pG=G;pBL=BL;pW=W;lines=curves=0}};while(i<n){let c=u[i];if(flatWs(c)){i++;continue}if(c===37){while(i<n&&u[i]!==10&&u[i]!==13)i++;continue}const st=i;if(c===40){i++;let d=1;while(i<n&&d){c=u[i];if(c===92){i+=2;continue}if(c===40)d++;else if(c===41)d--;i++}nn=0;continue}if(c===60){if(i+1<n&&u[i+1]===60)i+=2;else{i++;while(i<n&&u[i]!==62)i++;if(i<n)i++;nn=0;continue}}else if(c===91){i++;let d=1;while(i<n&&d){c=u[i];if(c===40){i++;let q=1;while(i<n&&q){c=u[i];if(c===92){i+=2;continue}if(c===40)q++;else if(c===41)q--;i++}continue}if(c===91)d++;else if(c===93)d--;i++}nn=0;continue}else if(c===47){i++;while(i<n&&!flatDelim(u[i]))i++;continue}else while(i<n&&!flatDelim(u[i]))i++;const tok=flatAscii(u,st,i),fc=tok.charCodeAt(0);if(tok&&((fc>=48&&fc<=57)||fc===43||fc===45||fc===46)){const z=Number(tok);if(Number.isFinite(z)){put(z,st);continue}}const op=tok;if(op==='q'){stack.push(A,B,C,D,E,F,R,G,BL,W)}else if(op==='Q'){if(stack.length>=10){W=stack.pop();BL=stack.pop();G=stack.pop();R=stack.pop();F=stack.pop();E=stack.pop();D=stack.pop();C=stack.pop();B=stack.pop();A=stack.pop()}}else if(op==='cm'&&nn>=6){const a=tail(6),b=tail(5),c2=tail(4),d=tail(3),e=tail(2),f=tail(1),na=A*a+C*b,nb=B*a+D*b,nc=A*c2+C*d,nd=B*c2+D*d,ne=A*e+C*f+E,nf=B*e+D*f+F;A=na;B=nb;C=nc;D=nd;E=ne;F=nf}else if(op==='RG'&&nn>=3){R=tail(3);G=tail(2);BL=tail(1)}else if(op==='G'&&nn>=1){R=G=BL=tail(1)}else if(op==='w'&&nn>=1)W=tail(1);else if(op==='m'&&nn>=2){begin(tailS(2));const p=P(tail(2),tail(1));add(p[0],p[1])}else if(op==='l'&&pOn&&nn>=2){const p=P(tail(2),tail(1));add(p[0],p[1]);lines++}else if(op==='c'&&pOn&&nn>=6){let p=P(tail(6),tail(5));add(p[0],p[1]);p=P(tail(4),tail(3));add(p[0],p[1]);p=P(tail(2),tail(1));add(p[0],p[1]);curves++}else if((op==='v'||op==='y')&&pOn&&nn>=4){if(op==='v')add(lx,ly);let p=P(tail(4),tail(3));add(p[0],p[1]);p=P(tail(2),tail(1));add(p[0],p[1]);if(op==='y')add(p[0],p[1]);curves++}else if(op==='re'&&nn>=4){begin(tailS(4));const x=tail(4),y=tail(3),w=tail(2),h=tail(1);for(const q of[[x,y],[x+w,y],[x+w,y+h],[x,y+h]]){const p=P(q[0],q[1]);add(p[0],p[1])}lines+=3}else if(op==='S'||op==='s'||op==='B'||op==='B*'||op==='b'||op==='b*'){if(pOn&&curves>0){const end=i,bbox=[x0,y0,x1,y1],first=[fx,fy],last=[lx,ly],built=flatCurveCmds(u,pStart,end,[pA,pB,pC,pD,pE,pF]),met=flatMetrics(built.cmds,bbox,first,last),orig=u.slice(pStart,end),rec={cmds:built.cmds,bbox,first,last,lines,curves,segs:lines+curves,width:pW,rgb:[pR,pG,pBL],closed:met.closed,chordNorm:met.chordNorm,lengthNorm:met.lengthNorm,start:pStart,end,sourceRef:ref,sourceBase,fx,fy,lx,ly,editable:true,cross:false,editRanges:[{ref,start:pStart,end}],locator:{root:0,names:[]},sourceKey:sourceBase+'|'+pStart+'|'+end,instanceKey:'P0|'+sourceBase+'|'+pStart+'|'+end,originalBytes:orig};out.push(rec)}pOn=false}else if(op==='n'||op==='f'||op==='F'||op==='f*')pOn=false;nn=0}return{refs:[ref],strokes:out,incomplete:false,forms:0,locators,ordinalSafe:true,flatCurveExact:true,flatStreamLength:u.length,flatCompressedLength:info.compressed}}
function flatBytesEqualAt(u,start,v){if(!v||start<0||start+v.length>u.length)return false;for(let i=0;i<v.length;i++)if(u[start+i]!==v[i])return false;return true}
'''
marker = 'async function compactModel(page,epoch=-1,emit=null,collect=true){'
assert marker in core
core = core.replace(marker, insert + '\n' + marker, 1)

old_plan = "async function compactEditPlan(targets){const allCount=new Map(),selCount=new Map();for(const s of model.strokes)allCount.set(s.sourceKey,(allCount.get(s.sourceKey)||0)+1);for(const s of targets)selCount.set(s.sourceKey,(selCount.get(s.sourceKey)||0)+1);for(const[k,n]of selCount)if(n!==(allCount.get(k)||0))throw new Error('XObject compartido: una instancia no azul usa el mismo operador');const groups=strokeEditGroups(targets),plan=[];for(const g of groups.values()){const loc=model.locators.get(g.key);if(!loc)throw new Error('sin localizador estable para un stream seleccionado');const text=latin(g.ref.readStream()),ranges=[];for(const[a,b]of g.ranges){if(a<0||b>text.length||a>=b)throw new Error('rango seleccionado inválido');ranges.push({start:a,end:b,original:text.slice(a,b)})}plan.push({loc,length:text.length,digest:await compactTextDigest(text),ranges})}return plan}"
new_plan = "async function compactEditPlan(targets){const allCount=new Map(),selCount=new Map();for(const s of model.strokes)allCount.set(s.sourceKey,(allCount.get(s.sourceKey)||0)+1);for(const s of targets)selCount.set(s.sourceKey,(selCount.get(s.sourceKey)||0)+1);for(const[k,n]of selCount)if(n!==(allCount.get(k)||0))throw new Error('XObject compartido: una instancia no azul usa el mismo operador');const groups=strokeEditGroups(targets),plan=[];if(model?.flatCurveExact){const originals=new Map();for(const t of targets)for(const r of strokeEditRanges(t))originals.set(deepKey(r.ref)+'|'+r.start+'|'+r.end,t.originalBytes);for(const g of groups.values()){const loc=model.locators.get(g.key);if(!loc)throw new Error('sin localizador estable para un stream seleccionado');const ranges=[];for(const[a,b]of g.ranges){const original=originals.get(g.key+'|'+a+'|'+b);if(!original)throw new Error('rango azul sin prueba byte exacta');ranges.push({start:a,end:b,original})}plan.push({flat:true,loc,length:model.flatStreamLength,ranges})}return plan}for(const g of groups.values()){const loc=model.locators.get(g.key);if(!loc)throw new Error('sin localizador estable para un stream seleccionado');const text=latin(g.ref.readStream()),ranges=[];for(const[a,b]of g.ranges){if(a<0||b>text.length||a>=b)throw new Error('rango seleccionado inválido');ranges.push({start:a,end:b,original:text.slice(a,b)})}plan.push({loc,length:text.length,digest:await compactTextDigest(text),ranges})}return plan}"
assert old_plan in core
core = core.replace(old_plan,new_plan,1)

old_apply = "async function applyCompactPlan(work,plan){let page=null,touched=0;try{page=work.loadPage(0);for(const g of plan){const ref=directResolveCompactStream(page,g.loc);let text=latin(ref.readStream());if(text.length!==g.length||await compactTextDigest(text)!==g.digest)throw new Error('identidad del stream cambió en la copia');for(const r of g.ranges){if(text.slice(r.start,r.end)!==r.original)throw new Error('rango seleccionado cambió en la copia');text=text.slice(0,r.start)+text.slice(r.end)}ref.writeStream(raw(text));touched++}return touched}finally{try{page?.destroy?.()}catch(_){}}}"
new_apply = "async function applyCompactPlan(work,plan){let page=null,touched=0;try{page=work.loadPage(0);for(const g of plan){const ref=directResolveCompactStream(page,g.loc);if(g.flat){const buf=ref.readStream(),u=U(buf);if(u.length!==g.length)throw new Error('longitud del stream cambió en la copia');for(const r of g.ranges){if(!flatBytesEqualAt(u,r.start,r.original))throw new Error('rango seleccionado cambió en la copia');u.fill(32,r.start,r.end)}ref.writeStream(u);touched++;continue}let text=latin(ref.readStream());if(text.length!==g.length||await compactTextDigest(text)!==g.digest)throw new Error('identidad del stream cambió en la copia');for(const r of g.ranges){if(text.slice(r.start,r.end)!==r.original)throw new Error('rango seleccionado cambió en la copia');text=text.slice(0,r.start)+text.slice(r.end)}ref.writeStream(raw(text));touched++}return touched}finally{try{page?.destroy?.()}catch(_){}}}"
assert old_apply in core
core = core.replace(old_apply,new_apply,1)

old_v = re.search(r"function verifyVisualSequence\(page,selectedOrdinals\)\{.*?return\{ok,why,seen\}\}", core)
assert old_v
new_v = r'''function verifyVisualSequence(page,selectedOrdinals){if(model?.flatCurveExact){const m=flatGiantExactModel(page,true);if(!m)return{ok:false,why:'no se pudo reconstruir el índice exacto de nubes',seen:0};const skip=new Set(selectedOrdinals);let e=0,seen=0,ok=true,why='';for(let i=0;i<classicVisual.length;i++){if(skip.has(i))continue;const q=m.strokes[e++];if(!q||sig(q)!==sig(classicVisual[i])){ok=false;why='la geometría de nubes restante diverge en '+i;break}seen++}if(ok&&e!==m.strokes.length){ok=false;why='apareció geometría de nubes adicional'}flatVerifyCache={page,m,ok};return{ok,why,seen}}const skip=new Set(selectedOrdinals);let expected=0,seen=0,ok=true,why='';const next=()=>{while(expected<classicVisual.length&&skip.has(expected))expected++};next();const cb={strokePath(path,stroke,ctm,cs,color){if(!ok)return;const r=visualRecord(path,stroke,ctm,color);if(!r)return;if(expected>=classicVisual.length){ok=false;why='apareció geometría adicional';return}if(!visualSigEqual(r,classicVisual[expected])){ok=false;why='la geometría restante diverge en el ordinal '+expected;return}expected++;seen++;next()}};let dev=null;try{dev=new mupdf.Device(cb);page.run(dev,mupdf.Matrix.identity)}finally{try{dev?.close?.()}catch(_){}try{dev?.destroy?.()}catch(_){}}next();if(expected!==classicVisual.length){ok=false;why=why||'faltan trazos no azules'}if(seen!==classicVisual.length-selectedOrdinals.length){ok=false;why=why||'conteo visual inesperado'}return{ok,why,seen}}'''
core = core[:old_v.start()] + new_v + core[old_v.end():]

old_s = re.search(r"async function verifyCompactStructure\(page,selectedOrdinals\)\{.*?return\{ok,why,seen\}\}", core)
assert old_s
new_s = r'''async function verifyCompactStructure(page,selectedOrdinals){if(model?.flatCurveExact){const m=(flatVerifyCache&&flatVerifyCache.page===page&&flatVerifyCache.ok)?flatVerifyCache.m:flatGiantExactModel(page,true);if(!m)return{ok:false,why:'no se pudo reconstruir la estructura exacta de nubes',seen:0};const skip=new Set(selectedOrdinals);let e=0,seen=0;for(let i=0;i<model.strokes.length;i++){if(skip.has(i))continue;const q=m.strokes[e++];if(!q||!compactGeomMatch(model.strokes[i],q))return{ok:false,why:'estructura de nubes restante diverge en '+i,seen};seen++}if(e!==m.strokes.length)return{ok:false,why:'conteo estructural de nubes inesperado',seen};return{ok:true,why:'',seen}}const skip=new Set(selectedOrdinals);let expected=0,seen=0,ok=true,why='';const next=()=>{while(expected<model.strokes.length&&skip.has(expected))expected++};next();const r=await compactModel(page,-1,q=>{if(!ok)return;if(expected>=model.strokes.length){ok=false;why='estructura adicional';return}if(!compactGeomMatch(model.strokes[expected],q)){ok=false;why='estructura restante diverge en '+expected;return}expected++;seen++;next()},false);next();if(r.incomplete){ok=false;why=why||'recorrido estructural incompleto'}if(expected!==model.strokes.length||seen!==model.strokes.length-selectedOrdinals.length){ok=false;why=why||'conteo estructural inesperado'}return{ok,why,seen}}'''
core = core[:old_s.start()] + new_s + core[old_s.end():]

old_render = "try{\n  classicVisual=collectVisual(p);for(let i=0;i<classicVisual.length;i++)classicVisual[i]._ordinal=i;analysisReady=true;setButtons();\n  status.textContent='Selector listo · visual='+classicVisual.length+' · construyendo índice estructural compacto…';\n }finally{try{p.destroy?.()}catch(_){}}\n indexPromise=startCompactIndex();\n if('requestIdleCallback'in window)requestIdleCallback(()=>scheduleSharp(80),{timeout:4500});else scheduleSharp(2500)"
new_render = "try{\n  const flat=flatGiantExactModel(p,false);if(flat){classicVisual=flat.strokes;for(let i=0;i<classicVisual.length;i++)classicVisual[i]._ordinal=i;model=flat;analysisReady=true;indexReady=true;indexPromise=Promise.resolve(flat);setButtons();status.textContent='Selector listo · '+classicVisual.length+' arcos de nube indexados exactamente · página gigante sin duplicar millones de líneas.';return}\n  classicVisual=collectVisual(p);for(let i=0;i<classicVisual.length;i++)classicVisual[i]._ordinal=i;analysisReady=true;setButtons();\n  status.textContent='Selector listo · visual='+classicVisual.length+' · construyendo índice estructural compacto…';\n }finally{try{p.destroy?.()}catch(_){}}\n indexPromise=startCompactIndex();\n if('requestIdleCallback'in window)requestIdleCallback(()=>scheduleSharp(80),{timeout:4500});else scheduleSharp(2500)"
assert old_render in core
core = core.replace(old_render,new_render,1)

# Reset the verification cache whenever a new page/model is rendered.
